window.MOTIF_CATALOG_CHUNKS[39]={"cards":[{"id":"MEJE-KW-001674","row_version":1,"title":"고통 끝에 터지는 사랑 고백","original":"Anguished Declaration of Love","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"숨겨 온 마음이 위기나 갈등 속에서 더는 감춰지지 않아 격한 고백으로 나오는 관계 장면. 고백의 절박함과 상대가 응답할 자유를 함께 다루면 관계의 긴장이 선명해진다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001674/index.html"},{"id":"MEJE-KW-001675","row_version":1,"title":"슬픔과 분노가 함께 터지는 절규","original":"Anguished Outburst","aliases":[],"kind":"keyword","facet_id":"ML-F19","node_kind":null,"parent_id":null,"tag_path":["ML-F19"],"summary":"상실이나 불의 앞에서 슬픔과 화가 한꺼번에 말과 몸짓으로 터져 나오는 정서 장면. 누군가를 향한 비난과 자신이 잃은 것에 대한 애도가 겹칠 수 있다.","accent":"#9B7F74","tab":"#9A6A55","facet":"정서·톤","bookmark":"분류축","entry_url":"cards/MEJE-KW-001675/index.html"},{"id":"MEJE-KW-001677","row_version":1,"title":"얼음 능력자의 복장 대비","original":"An Ice Suit","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"얼음을 다루는 인물을 두꺼운 방한복이나 오히려 가벼운 옷차림으로 보여 주는 시각 선택. 복장은 능력의 위험, 추위에 대한 내성, 인물의 성격을 빠르게 전달한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-001677/index.html"},{"id":"MEJE-KW-001678","row_version":1,"title":"암살 수단으로 쓰인 동물","original":"Animal Assassin","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00776","ML-T00784"],"summary":"누군가가 동물을 은밀히 풀어 놓거나 조종해 특정 인물을 해치려는 이야기 장치. 동물이 스스로 움직이는지, 가해자가 어떻게 통제하는지가 사건의 설득력을 좌우한다.","accent":"#9B7160","tab":"#7D8FA3","facet":"사건·행동","bookmark":"암살","entry_url":"cards/MEJE-KW-001678/index.html"},{"id":"MEJE-KW-001679","row_version":1,"title":"규정의 빈틈으로 경기에 나선 동물","original":"Animal Athlete Loophole","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"스포츠 팀이 규칙에 동물 선수 금지 조항이 없다는 논리를 내세워 동물을 경기에 참가시키는 전개. 규정 해석의 억지를 웃음과 승부의 반전으로 사용한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001679/index.html"},{"id":"MEJE-KW-001680","row_version":1,"title":"인간에게 호감을 보이는 동물 인물","original":"Animal Attracted to Human","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"사람처럼 생각하고 감정을 표현하는 동물 인물이 인간에게 호감을 품는 설정. 동물의 지능과 자율성, 관계의 힘 차이를 작품의 전제 안에서 분명히 해야 한다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001680/index.html"},{"id":"MEJE-KW-001681","row_version":2,"title":"동물 형상의 전투 기운","original":"Animal Battle Aura","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"무술가가 기술을 쓸 때 뒤나 주변에 동물의 모습이 기운처럼 나타나는 연출. 상징적 이미지인지 실제 공격력이 있는 존재인지는 세계관 규칙에 따라 구분한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001681/index.html"},{"id":"MEJE-KW-001682","row_version":1,"title":"동물을 매개로 호감을 얻는 인물","original":"Animal Chick Magnet","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"인물이 반려동물과의 교감을 대화의 계기로 삼아 다른 사람의 관심을 얻는 관계 장치. 동물을 소품으로만 쓰는지 실제 유대가 있는지도 인물 평가에 영향을 준다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001682/index.html"},{"id":"MEJE-KW-001683","row_version":1,"title":"동물의 모습으로 위장하기","original":"Animal Disguise","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07","ML-T00786","ML-T00787"],"summary":"인물이 동물 의상이나 외피를 써서 숨어들거나 누군가를 속이는 행동. 위장의 정교함보다 그것이 통하는 이야기의 규칙과 실패 가능성이 긴장을 만든다.","accent":"#9B7160","tab":"#A07A87","facet":"사건·행동","bookmark":"위장","entry_url":"cards/MEJE-KW-001683/index.html"},{"id":"MEJE-KW-001684","row_version":2,"title":"장식용 동물 귀 머리띠","original":"Animal-Eared Headband","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16","ML-T01436"],"summary":"실제 신체가 아닌 머리띠나 모자에 동물 귀를 붙여 인물의 이미지를 바꾸는 장신구. 의인화 동물의 진짜 귀와 구분하며 귀여움, 역할놀이, 소속 표시 등에 쓰인다.","accent":"#8E8263","tab":"#A58A4E","facet":"사물·도구·자원","bookmark":"의복·장신구","entry_url":"cards/MEJE-KW-001684/index.html"},{"id":"MEJE-KW-001685","row_version":1,"title":"첩보에 동원된 동물","original":"Animal Espionage","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"동물이 사람들의 눈을 피해 정보를 모으거나 전달하는 첩보 장치. 훈련받은 동물인지 스스로 판단하는 인물인지, 동물의 눈을 빌려 보기처럼 다른 존재가 감각을 공유하는지도 구분한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001685/index.html"},{"id":"MEJE-KW-001686","row_version":2,"title":"동물처럼 생긴 눈","original":"Animal Eyes","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20","ML-T01720"],"summary":"사람 형태의 인물에게 동물과 닮은 눈동자나 시선을 주어 비인간적 정체성을 암시하는 이미지. 겉모습의 표지와 실제 시각 능력이 같은 뜻인지는 별도로 설정한다.","accent":"#85835C","tab":"#8B739C","facet":"상징·이미지","bookmark":"신체 이미지","entry_url":"cards/MEJE-KW-001686/index.html"},{"id":"MEJE-KW-001687","row_version":1,"title":"동물의 눈을 빌려 보기","original":"Animal Eye Spy","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17","ML-T01490","ML-T01493"],"summary":"인물이 동물과 감각을 이어 그 동물이 보는 장면을 자신의 시야처럼 받아들이는 능력. 범위, 동시 연결 수, 동물이 겪는 위험이 사용자에게 돌아오는지를 규칙으로 정한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"초인적 감각","entry_url":"cards/MEJE-KW-001687/index.html"},{"id":"MEJE-KW-001688","row_version":2,"title":"동물에 덧붙인 사람식 수염","original":"Animal Facial Hair","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20","ML-T01720"],"summary":"동물 캐릭터에게 사람의 콧수염이나 턱수염을 더해 나이, 성별 이미지, 성격을 표시하는 디자인 관습. 원래 종의 털이나 무늬와 인위적 얼굴 표지를 구분한다.","accent":"#85835C","tab":"#8B739C","facet":"상징·이미지","bookmark":"신체 이미지","entry_url":"cards/MEJE-KW-001688/index.html"},{"id":"MEJE-KW-001690","row_version":1,"title":"동물의 성별 특징을 뒤섞어 그리기","original":"Animal Gender-Bender","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 동물 종의 성별에 따라 다른 외형 특징을 구분하지 않거나 의도적으로 바꾸어 그리는 관습. 실제 생물의 예외와 종 차이가 있으므로 특정 묘사를 곧바로 생물학적 오류로 단정하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001690/index.html"},{"id":"MEJE-KW-001691","row_version":2,"title":"학교에 들어온 동물","original":"Animal Goes to School","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"평소 동물이 다니지 않는 학교에 동물이 들어오면서 숨기기, 소동, 위험 대처가 벌어지는 전개. 동물 학생이 원래 정상인 세계관과는 구분한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001691/index.html"},{"id":"MEJE-KW-001692","row_version":2,"title":"사람이 사라진 뒤 사회를 이룬 동물","original":"Animal Is the New Man","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"인류가 약해지거나 사라진 뒤 동물이 새로운 사회의 중심이 되는 미래 세계. 동물이 언어와 제도를 갖추는 방식, 남은 인간과의 관계가 세계관의 핵심이다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001692/index.html"},{"id":"MEJE-KW-001693","row_version":2,"title":"변신 없이 쓰는 동물의 능력","original":"Animalistic Abilities","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17","ML-T01490"],"summary":"인물이 동물로 몸을 바꾸지 않고 동물의 감각이나 신체 능력만 빌려 쓰는 설정. 동물의 눈을 빌려 보기처럼 특정 감각에 한정될 수도 있고 여러 능력을 조합할 수도 있다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"신체 능력","entry_url":"cards/MEJE-KW-001693/index.html"},{"id":"MEJE-KW-001694","row_version":1,"title":"동물을 닮은 초월적 괴물","original":"Animalistic Abomination","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"이해하기 어려운 초월적 존재를 친숙한 동물의 윤곽과 결합해 그리는 괴물 유형. 알아볼 수 있는 형상과 설명할 수 없는 힘의 차이가 공포를 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001694/index.html"},{"id":"MEJE-KW-001695","row_version":1,"title":"종이 다르다는 이유로 대립하는 동물들","original":"Animal Jingoism","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"작품 속 동물 종들이 개별 인물의 경험과 무관하게 오래된 적대 관계를 가진 것처럼 행동하는 설정. 실제 생태 관계를 그대로 옮겼다고 보기보다 이야기 속 집단 규범과 편견을 살핀다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001695/index.html"},{"id":"MEJE-KW-001696","row_version":1,"title":"야생을 다스리는 동물 군주","original":"Animal Lord of the Wilds","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"숲이나 산의 일부를 지배하며 다른 생명에게 권위를 인정받는 동물 존재. 단순히 큰 맹수가 아니라 영역의 질서와 생태적 활력을 상징하도록 쓰인다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001696/index.html"},{"id":"MEJE-KW-001697","row_version":2,"title":"동물을 아끼는 인물","original":"Animal Lover","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"여러 동물에게 친밀감과 관심을 보이는 인물 유형. 마음만 앞서는지 실제 돌봄의 지식과 책임을 갖추었는지에 따라 인물의 성격이 달리 드러난다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001697/index.html"},{"id":"MEJE-KW-001698","row_version":2,"title":"동물이 덮쳐 움직임을 묶는 공격","original":"Animal Maul Attack","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임에서 동물이 대상을 쓰러뜨리고 붙잡은 동안 연속 피해를 주는 공격 규칙. 동물과 대상이 다른 행동을 못 하는 시간, 탈출 조건, 후유 효과가 전투의 긴장을 만든다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001698/index.html"},{"id":"MEJE-KW-001699","row_version":1,"title":"동물 형상을 한 거대 기체","original":"Animal Mecha","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"동물의 머리와 몸체를 본뜬 거대한 기계나 탑승 병기. 단순한 장식인지 움직임과 능력이 해당 동물의 특징을 활용하는지 구분한다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001699/index.html"},{"id":"MEJE-KW-001700","row_version":2,"title":"동물 관계로 인물 관계를 비추기","original":"Animal Metaphor","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"두 동물의 행동이나 관계를 통해 사람 인물 사이의 갈등과 친밀함을 간접적으로 드러내는 상징 장치. 동물 상징 가운데 관계의 대응을 특히 강조하는 경우다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-001700/index.html"},{"id":"MEJE-KW-001701","row_version":2,"title":"동물 상징","original":"Animal Motifs","aliases":[],"kind":"keyword","facet_id":"ML-F20","node_kind":null,"parent_id":null,"tag_path":["ML-F20"],"summary":"동물의 형상, 이름, 흔적을 인물이나 주제의 의미를 드러내는 반복 이미지로 쓰는 방식. 작품 속 실제 동물이 없어도 문양과 별명, 소품만으로 상징을 만들 수 있다.","accent":"#85835C","tab":"#9A6A55","facet":"상징·이미지","bookmark":"분류축","entry_url":"cards/MEJE-KW-001701/index.html"},{"id":"MEJE-KW-001702","row_version":2,"title":"서로 다른 동물 상징을 맡은 팀","original":"Animal-Motif Team","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"팀원마다 다른 동물의 이름이나 형상을 부여해 능력과 성격을 구별하는 집단 구성. 동물 상징을 개인 표지로 나누어 팀 전체의 관계를 읽게 한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001702/index.html"},{"id":"MEJE-KW-001703","row_version":2,"title":"동물 사회의 이름 짓기 규칙","original":"Animal Naming Conventions","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"동물 인물이 외모, 서열, 성장 단계 또는 집단 소속에 따라 이름을 얻고 바꾸는 세계관 관습. 사람의 이름과 다른 규칙을 세우면 그 사회의 기억과 가치관이 드러난다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001703/index.html"},{"id":"MEJE-KW-001704","row_version":1,"title":"한 동물에게 집착하는 사냥꾼","original":"Animal Nemesis","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"사냥꾼이 특정 동물을 숙적으로 정하고 오랜 원한을 좇는 인물 동기. 그 동물이 실제로 적의를 가졌는지와 사냥꾼이 의미를 덧씌운 것인지를 분리해 볼 수 있다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001704/index.html"},{"id":"MEJE-KW-001705","row_version":1,"title":"동물 종에 직업 성격을 붙이기","original":"Animal Occupation Stereotypes","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"직업의 이미지를 특정 동물 종의 생김새나 통념에 연결해 인물을 빠르게 소개하는 관습. 동물에게 부여한 성격 고정관념이 직업의 평가로 확장되는 방식을 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001705/index.html"},{"id":"MEJE-KW-001706","row_version":1,"title":"동물의 반응으로 장면을 마무리하기","original":"Animal Reaction Shot","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"대화나 사건 뒤 동물의 표정과 소리를 짧게 보여 주어 관객의 반응을 대신하거나 농담의 박자를 만드는 연출. 동물이 실제로 무엇을 이해했는지는 작품의 설정에 달려 있다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001706/index.html"},{"id":"MEJE-KW-001707","row_version":1,"title":"동물 사회의 독자적 신앙","original":"Animal Religion","aliases":[],"kind":"keyword","facet_id":"ML-F15","node_kind":null,"parent_id":null,"tag_path":["ML-F15"],"summary":"지성을 지닌 동물 집단이 자신들의 역사와 생활에 맞는 신화, 의례, 신을 갖는 설정. 사람의 종교를 단순히 이름만 바꿔 옮길지 독자적인 문화로 만들지에 따라 세계의 깊이가 달라진다.","accent":"#8B795E","tab":"#9A6A55","facet":"사회·문화·생활","bookmark":"분류축","entry_url":"cards/MEJE-KW-001707/index.html"},{"id":"MEJE-KW-001708","row_version":1,"title":"동물이 다른 동물을 타고 이동하기","original":"Animal Rides Another","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"동물 인물이 다른 동물의 등에 올라타 이동하거나 도움을 받는 장면. 크기 차이, 관계의 동의, 실제 이동 능력을 어떻게 설정하는지가 장면의 의미를 정한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001708/index.html"},{"id":"MEJE-KW-001709","row_version":1,"title":"동물이 자동차를 운전하기","original":"Animals Driving Cars","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"동물이 사람의 차량을 조작해 이동하는 비현실적 장면. 동물이 사람처럼 판단하는 세계인지, 한 번의 희극적 예외인지를 구분한다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001709/index.html"},{"id":"MEJE-KW-001710","row_version":1,"title":"중성화 수술을 두려워하는 동물 인물","original":"Animals Fear Neutering","aliases":[],"kind":"keyword","facet_id":"ML-F11","node_kind":null,"parent_id":null,"tag_path":["ML-F11"],"summary":"말하거나 사람처럼 생각하는 동물 인물이 동물병원의 수술을 알고 두려워하거나 피하려 하는 허구적 반응. 실제 수의학적 판단을 대신하는 설명으로 쓰지 않는다.","accent":"#8E796B","tab":"#9A6A55","facet":"동기·심리","bookmark":"분류축","entry_url":"cards/MEJE-KW-001710/index.html"},{"id":"MEJE-KW-001711","row_version":2,"title":"동물에게 유독 미움받는 인물","original":"Animals Hate Him","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"평소 태도와 상관없이 여러 동물이 한 인물을 경계하거나 공격하는 반복 관습. 이유가 서사의 단서인지 우연한 농담인지에 따라 인물의 위치가 달라진다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001711/index.html"},{"id":"MEJE-KW-001712","row_version":1,"title":"동물의 신체 특징을 생략한 디자인","original":"Animals Lack Attributes","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"동물을 그릴 때 이야기와 그림체에 필요하지 않은 신체 세부를 덜어 내는 시각적 단순화. 생략 자체와 실제 생물의 몸을 잘못 설명하는 표현은 구분한다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-001712/index.html"},{"id":"MEJE-KW-001713","row_version":1,"title":"실제 비율과 다르게 그린 동물","original":"Animals Not to Scale","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"동물의 종별 크기 차이를 줄이거나 늘려 화면의 구도와 인물 관계에 맞추는 표현. 작품 세계 안의 실제 크기가 바뀐 것인지 화면상 양식화인지 분리해 본다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001713/index.html"},{"id":"MEJE-KW-001714","row_version":2,"title":"자연의 균형을 이해하는 동물","original":"Animals Respect Nature","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"동물 인물이 생태계의 관계를 의식하고 스스로 지키려 하는 모습을 통해 환경 보전의 주제를 전하는 설정. 동물의 실제 생태 행동에 인간의 윤리 의식을 그대로 투사한 사실 설명으로 다루지 않는다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-001714/index.html"},{"id":"MEJE-KW-001715","row_version":1,"title":"동물이 세상을 흑백으로 본다는 설정","original":"Animals See in Monochrome","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"동물의 시야를 회색조로만 보여 주어 사람과 다른 감각 세계를 표현하는 관습. 종마다 다른 시각을 하나로 단순화한 허구적 표현으로 설명한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001715/index.html"},{"id":"MEJE-KW-001716","row_version":1,"title":"동물 무리의 돌진","original":"Animal Stampede","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"여러 동물이 한꺼번에 달리며 인물과 공간을 휩쓰는 사건. 무리의 의도가 공격인지 도주인지 구분하면 장면의 위험과 책임이 달라진다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001716/index.html"},{"id":"MEJE-KW-001717","row_version":1,"title":"동물에게 부여한 성격 고정관념","original":"Animal Stereotypes","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"특정 종을 충직함, 교활함, 게으름 같은 사람의 성격으로 곧바로 읽는 표현 관습. 문화권과 작품마다 부여하는 의미가 다르며 실제 동물의 성질로 단정하지 않는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001717/index.html"},{"id":"MEJE-KW-001718","row_version":2,"title":"동물로 된 슈퍼히어로","original":"Animal Superheroes","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"동물 인물이 특별한 힘과 영웅의 임무를 지닌 주인공으로 활동하는 유형. 동물 이름만 빌린 사람 영웅과는 구별한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001718/index.html"},{"id":"MEJE-KW-001719","row_version":1,"title":"물건을 같은 종의 짝으로 오해하는 동물","original":"Animal Sweet on Object","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"동물 인물이 장난감이나 사물을 같은 종의 다른 동물로 착각해 구애하는 희극적 장면. 오해의 원인과 동물이 이를 알아차리는 순간이 웃음의 구조를 만든다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001719/index.html"},{"id":"MEJE-KW-001720","row_version":2,"title":"서로 다른 동물끼리 통하는 말","original":"Animal Talk","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"작품 속 여러 동물 종이 같은 방식으로 의사를 주고받지만 사람은 이를 알아듣지 못하는 소통 규칙. 말하는 동물과 달리 사람의 언어를 소리 내는 능력이 없어도 성립한다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001720/index.html"},{"id":"MEJE-KW-001721","row_version":2,"title":"동물 실험을 둘러싼 윤리 갈등","original":"Animal Testing","aliases":[],"kind":"keyword","facet_id":"ML-F18","node_kind":null,"parent_id":null,"tag_path":["ML-F18"],"summary":"작품이 동물에게 가해지는 실험과 인간의 연구 목적 사이에서 선택과 책임을 묻는 주제. 연구의 성과나 피해를 단순한 선악 구도로 줄이지 않고 인물의 근거와 제도적 조건을 드러낸다.","accent":"#7E8070","tab":"#9A6A55","facet":"주제·가치","bookmark":"분류축","entry_url":"cards/MEJE-KW-001721/index.html"},{"id":"MEJE-KW-001722","row_version":1,"title":"동물의 움직임을 본뜬 무술","original":"Animal-Themed Fighting Style","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"격투 인물이 동물의 자세와 움직임에서 형상을 따와 기술을 구성하는 방식. 실제 무술의 이름을 빌릴 수 있어도 작품 속 동작과 효능은 허구의 규칙으로 따로 설명한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001722/index.html"},{"id":"MEJE-KW-001723","row_version":2,"title":"동물 이미지를 쓰는 초인","original":"Animal-Themed Superbeing","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"사람 형태의 영웅이나 악역이 특정 동물의 이름, 외형, 힘을 정체성의 중심에 두는 인물 유형. 동물로 된 슈퍼히어로와 달리 인물 자체가 동물일 필요는 없다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001723/index.html"},{"id":"MEJE-KW-001724","row_version":1,"title":"동물 이름으로 묶은 명명 체계","original":"Animal Theme Naming","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"기체, 조직, 무기 또는 인물의 이름을 동물 어휘로 묶어 계열성과 이미지를 만드는 방식. 이름의 공통점이 세계 안의 소속을 뜻하는지 관객을 위한 상징인지를 살핀다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001724/index.html"},{"id":"MEJE-KW-001725","row_version":2,"title":"동물과 차량을 합친 존재","original":"Animal-Vehicle Hybrid","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"살아 있는 동물의 몸에 바퀴나 차체 같은 이동 수단의 특징이 붙은 혼합 존재. 동물 형상을 한 거대 기체처럼 기계가 동물을 흉내 낸 경우와는 출발점이 다르다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001725/index.html"},{"id":"MEJE-KW-001726","row_version":1,"title":"동물 보호 단체를 무모하게 그리기","original":"Animal Wrongs Group","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"작품이 동물 보호 단체를 피해를 따지지 않고 행동하는 집단으로 희화화하는 관습. 실제 단체의 성격을 일반화하기보다 작품이 어떤 행동과 결과를 배치했는지 비판적으로 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001726/index.html"},{"id":"MEJE-KW-001727","row_version":1,"title":"스스로 움직이고 말하는 신체 부위","original":"Animate Body Parts","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"손이나 코처럼 몸의 일부가 독자적인 의지와 목소리를 가진 존재로 그려지는 설정. 신체에서 분리되는지, 원래 사람의 의식과 충돌하는지가 이야기의 규칙을 만든다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001727/index.html"},{"id":"MEJE-KW-001728","row_version":1,"title":"만화 속 인물이 배우처럼 연기하기","original":"Animated Actors","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"애니메이션 인물이 이야기의 배역을 맡은 배우처럼 촬영장 밖에서 행동하는 메타 연출. 극중 성격과 연기 밖 성격의 차이로 작품의 약속을 뒤집는다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001728/index.html"},{"id":"MEJE-KW-001729","row_version":1,"title":"기존 작품을 애니메이션으로 각색하기","original":"Animated Adaptation","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"먼저 나온 이야기나 매체의 내용을 애니메이션 작품으로 다시 구성하는 제작 방식. 원작의 장면을 옮기는 데 그치지 않고 움직임과 소리, 표현 가능한 규모에 맞게 새 선택을 한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001729/index.html"},{"id":"MEJE-KW-001730","row_version":1,"title":"짧은 애니메이션을 묶은 앤솔러지","original":"Animated Anthology","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"서로 다른 짧은 애니메이션을 한 작품이나 프로그램 안에 모아 보여 주는 형식. 기존 작품의 재편집인지 새 작품의 공동 발표인지에 따라 전체 구성의 의미가 달라진다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-001730/index.html"},{"id":"MEJE-KW-001731","row_version":2,"title":"속이 빈 채 움직이는 갑옷","original":"Animated Armor","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"착용자가 없는데도 갑옷이 스스로 서고 싸우는 초자연적 존재. 빈 내부가 드러나는 순간 인물의 기대를 깨뜨리며 움직임의 근원이 서사의 질문이 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001731/index.html"},{"id":"MEJE-KW-001732","row_version":1,"title":"애니메이션으로 만든 출연진 도입부","original":"Animated Credits Opening","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"실사 작품의 시작이나 끝에 그림과 움직임으로 출연진과 제목을 소개하는 제작 형식. 본편과 다른 시각 언어로 장르 분위기나 사건의 단서를 미리 제시할 수 있다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001732/index.html"},{"id":"MEJE-KW-001733","row_version":1,"title":"시체를 하수인으로 일으키는 주문","original":"Animate Dead","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"마법 사용자가 죽은 몸을 움직여 명령을 따르는 전력으로 만드는 능력. 생전 인격의 부활과 구분하며 지속 시간, 통제 범위, 시전자가 사라졌을 때의 결과를 규칙으로 정한다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001733/index.html"},{"id":"MEJE-KW-001734","row_version":1,"title":"실사 시리즈의 애니메이션 회차","original":"Animated Episode","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"주로 실사로 이어지는 작품이 한 회차를 애니메이션으로 표현하는 형식 변화. 꿈이나 다른 세계라는 극중 이유가 있을 수도 있고 표현 방식 자체가 특별편의 목적일 수도 있다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-001734/index.html"},{"id":"MEJE-KW-001736","row_version":2,"title":"노래가 서사를 이끄는 애니메이션","original":"Animated Musical","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"인물의 목표와 갈등이 대사뿐 아니라 노래와 춤 장면을 통해 전개되는 애니메이션 뮤지컬. 배경음악이 많은 작품과 달리 노래 장면이 서사의 기능을 맡는다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-001736/index.html"},{"id":"MEJE-KW-001737","row_version":2,"title":"애니메이션으로 구성한 뮤직비디오","original":"Animated Music Video","aliases":[],"kind":"keyword","facet_id":"ML-F02","node_kind":null,"parent_id":null,"tag_path":["ML-F02"],"summary":"노래에 맞추어 그림, 인형, 컴퓨터 그래픽 등 움직이는 이미지로 영상의 대부분을 구성한 뮤직비디오. 가수의 실사 출연 여부보다 영상의 표현 형식이 중심이다.","accent":"#55758A","tab":"#9A6A55","facet":"미디어","bookmark":"분류축","entry_url":"cards/MEJE-KW-001737/index.html"},{"id":"MEJE-KW-001738","row_version":2,"title":"애니메이션 인물의 가짜 촬영 실수","original":"Animated Outtakes","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"애니메이션 인물이 실제 촬영 중인 배우처럼 대사를 틀리거나 장면을 망치는 모습을 일부러 만든 후일담 연출. 우연히 남은 실수 장면이 아니라 제작된 메타 농담이다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001738/index.html"},{"id":"MEJE-KW-001739","row_version":2,"title":"충격적인 소재로 웃음을 만드는 성인 애니메이션","original":"Animated Shock Comedy","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"금기와 거친 풍자를 웃음의 핵심 자원으로 삼는 성인 대상 애니메이션 코미디 유형. 충격만으로 범주를 정하지 않고 서사가 무엇을 비판하거나 소비하는지도 살핀다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-001739/index.html"},{"id":"MEJE-KW-001740","row_version":1,"title":"애니메이션 시트콤","original":"Animated Sitcom","aliases":[],"kind":"keyword","facet_id":"ML-F03","node_kind":null,"parent_id":null,"tag_path":["ML-F03"],"summary":"반복 등장하는 인물과 일상적 관계를 중심으로 회차마다 희극적 갈등을 풀어 가는 애니메이션 장르. 실사 촬영의 제약이 적어도 인물 관계의 축적이 형식의 핵심이다.","accent":"#8A687E","tab":"#9A6A55","facet":"장르","bookmark":"분류축","entry_url":"cards/MEJE-KW-001740/index.html"},{"id":"MEJE-KW-001741","row_version":1,"title":"살아 움직이는 문신","original":"Animated Tattoo","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"인물의 피부에 새긴 그림이 움직이거나 몸 밖으로 나와 독자적으로 행동하는 설정. 문신이 주인의 명령을 따르는지 스스로 의지를 지니는지가 능력의 성격을 가른다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001741/index.html"},{"id":"MEJE-KW-001742","row_version":3,"title":"애니메이션 세계가 스스로를 어떻게 보는가","original":"Animated World Hypotheses","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"애니메이션 속 인물이 자기 세계를 관객처럼 그려진 모습으로 지각하는지 묻는 세계관의 메타 규칙. 이야기 안의 대사나 물리 법칙이 이를 인정할 때 표현 양식이 세계의 사실로 바뀐다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001742/index.html"},{"id":"MEJE-KW-001743","row_version":2,"title":"한 가지 물질로 이루어진 살아 있는 존재","original":"Animate Inanimate Matter","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"살아 있지만 몸이 물이나 돌처럼 한 종류의 물질로 대부분 이루어진 존재 유형. 기관이 없는 몸의 움직임과 사고를 어떻게 성립시키는지가 세계관의 규칙이 된다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001743/index.html"},{"id":"MEJE-KW-001744","row_version":2,"title":"무생물이 스스로 움직이는 세계","original":"Animate Inanimate Object","aliases":[],"kind":"keyword","facet_id":"ML-F13","node_kind":null,"parent_id":null,"tag_path":["ML-F13"],"summary":"일상에서는 움직이지 않는 물건이 의지나 힘을 얻어 스스로 행동하는 설정. 살아 움직이는 문신이나 속이 빈 채 움직이는 갑옷처럼 특정 대상에 한정할 수도 있다.","accent":"#497A73","tab":"#9A6A55","facet":"세계관·규칙","bookmark":"분류축","entry_url":"cards/MEJE-KW-001744/index.html"},{"id":"MEJE-KW-001745","row_version":1,"title":"뿌리와 가지를 움직여 행동하는 식물","original":"Animate Plant","aliases":[],"kind":"keyword","facet_id":"ML-F12","node_kind":null,"parent_id":null,"tag_path":["ML-F12"],"summary":"평범한 식물처럼 보이지만 스스로 몸을 옮기거나 가지를 뻗어 행동하는 존재. 말하는 얼굴이 없어도 이동과 의도적인 움직임만으로 생명체의 역할이 바뀐다.","accent":"#62816F","tab":"#9A6A55","facet":"존재·종족","bookmark":"분류축","entry_url":"cards/MEJE-KW-001745/index.html"},{"id":"MEJE-KW-001746","row_version":1,"title":"사물에 움직임을 주는 유물","original":"Animating Artifact","aliases":[],"kind":"keyword","facet_id":"ML-F16","node_kind":null,"parent_id":null,"tag_path":["ML-F16"],"summary":"닿은 물건이나 재료를 스스로 움직이게 하는 힘을 지닌 유물. 유물이 떨어지거나 파괴된 뒤에도 움직임이 남는지에 따라 이야기의 약점과 책임이 달라진다.","accent":"#8E8263","tab":"#9A6A55","facet":"사물·도구·자원","bookmark":"분류축","entry_url":"cards/MEJE-KW-001746/index.html"},{"id":"MEJE-KW-001747","row_version":2,"title":"애니메이션은 어린이용이라는 편견","original":"Animation Age Ghetto","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"애니메이션이라는 표현 형식만 보고 작품의 주제와 대상 연령을 미리 좁혀 판단하는 수용 관습. 개별 작품의 실제 내용과 매체 전체에 대한 선입견을 구분한다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001747/index.html"},{"id":"MEJE-KW-001748","row_version":1,"title":"그림체로 표시하는 나이 변화","original":"Animation Anatomy Aging","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"애니메이션이나 만화에서 인물의 성장과 노화를 눈, 얼굴 윤곽, 자세 같은 시각 신호로 단계적으로 보여 주는 방식. 과장된 표지는 읽기 쉽지만 나이와 성별의 몸을 하나의 형태로 고정하지 않도록 살핀다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001748/index.html"},{"id":"MEJE-KW-001749","row_version":2,"title":"중요 장면에서만 높아지는 애니메이션 품질","original":"Animation Bump","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"작품 전체보다 특정 장면에서 움직임과 배경의 완성도가 눈에 띄게 높아지는 제작상의 변화. 시리즈를 따라 지속해서 바뀌는 애니메이션 움직임과 달리 국소적 강조에 가깝다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001749/index.html"},{"id":"MEJE-KW-001750","row_version":1,"title":"시리즈를 따라 지속해서 바뀌는 애니메이션 움직임","original":"Animation Evolution","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"애니메이션 시리즈의 움직임과 작화의 안정성이 여러 회차에 걸쳐 지속적으로 달라지는 현상. 한 장면의 집중 제작과 구별하며 제작 방식과 팀의 변화가 화면에 남는 모습을 다룬다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001750/index.html"},{"id":"MEJE-KW-001751","row_version":2,"title":"외국 인물의 말투를 현지어처럼 처리하기","original":"Anime Accent Absence","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"일본 애니메이션에서 외국 출신 인물이 별도 억양 없이 자연스러운 일본어를 쓰도록 표현하는 언어 관습. 작품 안의 실제 언어와 관객에게 전달되는 대사를 분리해 생각한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001751/index.html"},{"id":"MEJE-KW-001752","row_version":2,"title":"일본 애니메이션의 가톨릭풍 허구 설정","original":"Anime Catholicism","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"일본 애니메이션이 가톨릭의 복식과 조직 이미지를 차용해 초자연적 전투 집단이나 새로운 종교 질서로 재구성하는 관습. 실제 종교의 교리와 제도를 설명하는 자료로 보지 않고 창작 설정으로 다룬다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001752/index.html"},{"id":"MEJE-KW-001753","row_version":2,"title":"중국 여성 인물을 기호로만 그리는 관습","original":"Anime Chinese Girl","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"중국 출신 여성 인물에게 특정 옷차림, 머리 모양, 말버릇, 무술을 반복해서 부여하는 유형화. 한 인물의 개성을 문화권 전체의 성질로 바꾸지 않도록 표현의 맥락을 비판적으로 살핀다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001753/index.html"},{"id":"MEJE-KW-001754","row_version":1,"title":"원작 없이 먼저 기획한 일본 애니메이션","original":"Anime First","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"만화나 소설을 옮긴 결과가 아니라 애니메이션 제작 자체를 출발점으로 삼은 작품의 제작 경로. 이후 다른 매체로 확장될 수 있어도 최초의 기획 매체를 구분한다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001754/index.html"},{"id":"MEJE-KW-001755","row_version":1,"title":"과장된 일본 애니메이션식 머리 디자인","original":"Anime Hair","aliases":[],"kind":"keyword","facet_id":"ML-F21","node_kind":null,"parent_id":null,"tag_path":["ML-F21"],"summary":"인물의 윤곽을 빠르게 구별하도록 머리카락의 색과 형태를 비현실적으로 강조하는 디자인 관습. 장면 안에서 실제로 특이한 머리인지 시각적 약속인지는 작품의 규칙에 달려 있다.","accent":"#947C8F","tab":"#9A6A55","facet":"미학·스타일","bookmark":"분류축","entry_url":"cards/MEJE-KW-001755/index.html"},{"id":"MEJE-KW-001756","row_version":1,"title":"일본을 애니메이션 이미지로만 그린 세계","original":"Animeland","aliases":[],"kind":"keyword","facet_id":"ML-F28","node_kind":null,"parent_id":null,"tag_path":["ML-F28"],"summary":"일본의 실제 사회 대신 일부 대중문화 이미지만 모아 환상적인 나라처럼 재현하는 관습. 장난스러운 패러디인지 문화적 고정관념의 반복인지 장면의 관점과 대상에 따라 다르게 읽는다.","accent":"#93856B","tab":"#9A6A55","facet":"변주·관습","bookmark":"분류축","entry_url":"cards/MEJE-KW-001756/index.html"},{"id":"MEJE-KW-001757","row_version":2,"title":"다른 작품을 일본 애니메이션 오프닝처럼 꾸미기","original":"Anime Opening Parody","aliases":[],"kind":"keyword","facet_id":"ML-F27","node_kind":null,"parent_id":null,"tag_path":["ML-F27"],"summary":"원래 다른 형식의 작품이나 사건에 일본 애니메이션풍 노래와 영상 도입부를 덧씌우는 패러디. 대상의 분위기와 오프닝 관습 사이의 간격이 웃음이나 애정 어린 인용을 만든다.","accent":"#7F8A85","tab":"#9A6A55","facet":"메타·제작·유통","bookmark":"분류축","entry_url":"cards/MEJE-KW-001757/index.html"},{"id":"MEJE-KW-001758","row_version":2,"title":"일본 애니메이션의 주제가","original":"Anime Theme Song","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"일본 애니메이션의 시작이나 끝에 놓여 작품의 분위기와 인물 이미지를 압축하는 노래. 독립 음원으로도 소비될 수 있지만 카드에서는 작품과 노래가 맺는 서사적 관계에 초점을 둔다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001758/index.html"},{"id":"MEJE-KW-001759","row_version":1,"title":"이주자의 새 사회 적응 이야기","original":"An Immigrant's Tale","aliases":[],"kind":"keyword","facet_id":"ML-F05","node_kind":null,"parent_id":null,"tag_path":["ML-F05"],"summary":"인물이나 가족이 다른 나라로 옮긴 뒤 언어, 생계, 소속감의 변화를 겪는 이야기 구조. 성공담과 차별·상실의 경험을 하나의 필수 경로로 묶지 않고 선택한 인물의 시각에 따라 서술한다.","accent":"#6A748C","tab":"#9A6A55","facet":"서사 구조","bookmark":"분류축","entry_url":"cards/MEJE-KW-001759/index.html"},{"id":"MEJE-KW-001760","row_version":1,"title":"동물의 모습으로 변하기","original":"Animorphism","aliases":[],"kind":"keyword","facet_id":"ML-F17","node_kind":null,"parent_id":null,"tag_path":["ML-F17"],"summary":"인물이 자신의 뜻이나 외부의 힘으로 몸을 동물 형태로 바꾸는 능력과 사건. 변신 뒤의 기억, 언어, 행동 가능 범위가 인물 관계와 세계의 규칙을 바꾼다.","accent":"#75799A","tab":"#9A6A55","facet":"능력·기술·초자연","bookmark":"분류축","entry_url":"cards/MEJE-KW-001760/index.html"},{"id":"MEJE-KW-001761","row_version":2,"title":"기묘한 편집으로 이어 붙인 팬 애니메이션","original":"Animutation","aliases":[],"kind":"keyword","facet_id":"ML-F04","node_kind":null,"parent_id":null,"tag_path":["ML-F04"],"summary":"서로 다른 이미지와 짧은 움직임을 빠른 음악에 맞춰 이어 붙여 낯선 연상을 만드는 팬 영상 형식. 익숙한 대중문화 자료를 반복하고 비틀어 공동체의 유머를 만든다.","accent":"#7E7970","tab":"#9A6A55","facet":"형식·구성·규모","bookmark":"분류축","entry_url":"cards/MEJE-KW-001761/index.html"},{"id":"MEJE-KW-001762","row_version":2,"title":"손과 소품을 따로 찍어 끼운 삽입 숏","original":"An Insert","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"장면의 흐름 속에 손, 문서, 도구 같은 세부를 별도로 촬영한 가까운 화면으로 끼워 넣는 영상 기법. 본 장면과 화면 속 움직임을 이어 보이게 하면서 중요한 정보를 강조한다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001762/index.html"},{"id":"MEJE-KW-001763","row_version":3,"title":"게임 공간을 직접 꾸미기","original":"An Interior Designer Is You","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어가 게임 속 방이나 기지를 가구와 장식으로 바꾸는 상호작용. 가구와 집 꾸미기를 보상으로 주는 게임과 달리 보상을 받는 순간보다 배치와 선택의 자유가 중심이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001763/index.html"},{"id":"MEJE-KW-001764","row_version":1,"title":"발목을 붙잡혀 끌려가기","original":"Ankle Drag","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"인물이 보이지 않는 힘이나 괴물에게 발목을 붙잡혀 어둠이나 물속으로 끌려가는 장면. 손으로 바닥을 짚으며 버티는 동작이 구조의 시급함을 드러낸다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001764/index.html"},{"id":"MEJE-KW-001765","row_version":1,"title":"게임 속 아나운서의 끊임없는 해설","original":"Announcer Chatter","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"게임 진행 중 이름, 점수, 승패를 알리는 목소리가 반복해서 들리는 구성. 정보를 빠르게 전할 수 있지만 빈도와 음량에 따라 플레이의 긴장이나 피로감이 달라진다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001765/index.html"},{"id":"MEJE-KW-001766","row_version":1,"title":"화살을 가벼운 상처처럼 넘기기","original":"Annoying Arrows","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"작품 속 인물이 화살을 맞고도 큰 제약 없이 계속 움직이는 표현 관습. 인물의 강인함을 보이는 허구의 장치로 설명하며 실제 부상의 경중을 판단하는 근거로 쓰지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001766/index.html"},{"id":"MEJE-KW-001767","row_version":2,"title":"뒤에서 반복되어 인물을 거슬리게 하는 사건","original":"Annoying Background Event","aliases":[],"kind":"keyword","facet_id":"ML-F22","node_kind":null,"parent_id":null,"tag_path":["ML-F22"],"summary":"장면의 중심 바깥에서 같은 소리나 행동이 계속되어 인물이 집중하지 못하는 연출. 관객도 점차 반복을 알아차리게 하면서 작은 자극을 갈등으로 키운다.","accent":"#688397","tab":"#9A6A55","facet":"시각·공간 연출","bookmark":"분류축","entry_url":"cards/MEJE-KW-001767/index.html"},{"id":"MEJE-KW-001768","row_version":1,"title":"식사 자리를 방해하는 연주자","original":"Annoying Dinner Music","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"손님이 원하지 않는데도 식탁 가까이 와 계속 연주하는 음악가가 장면의 대화와 분위기를 방해하는 전개. 연주 실력보다 거리와 타이밍을 무시하는 행동이 갈등의 원인이다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001768/index.html"},{"id":"MEJE-KW-001769","row_version":1,"title":"거슬리는 웃음소리로 기억되는 인물","original":"Annoying Laugh","aliases":[],"kind":"keyword","facet_id":"ML-F24","node_kind":null,"parent_id":null,"tag_path":["ML-F24"],"summary":"작품이 특이한 웃음의 리듬과 음색을 반복해 인물의 존재를 알리는 소리 관습. 실제 사람의 웃음을 평가하는 기준이 아니라 장면이 만든 인상을 다룬다.","accent":"#8A7893","tab":"#9A6A55","facet":"소리·음악","bookmark":"분류축","entry_url":"cards/MEJE-KW-001769/index.html"},{"id":"MEJE-KW-001770","row_version":1,"title":"같은 말과 행동을 계속하는 아이","original":"Annoyingly Repetitive Child","aliases":[],"kind":"keyword","facet_id":"ML-F07","node_kind":null,"parent_id":null,"tag_path":["ML-F07"],"summary":"아이가 질문이나 놀이를 반복해 곁에 있는 인물이 지치거나 짜증을 내는 장면. 반복의 이유와 어른의 반응을 함께 보여 주면 아이를 단순한 방해물로만 만들지 않는다.","accent":"#9B7160","tab":"#9A6A55","facet":"사건·행동","bookmark":"분류축","entry_url":"cards/MEJE-KW-001770/index.html"},{"id":"MEJE-KW-001771","row_version":1,"title":"간병하는 사람에게 지나치게 요구하는 환자","original":"Annoying Patient","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"돌봄을 받는 인물이 요청을 계속 늘리거나 병세를 핑계로 상대를 부리는 희극적 인물 유형. 질병 자체와 상대를 대하는 행동을 구분해 묘사한다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001771/index.html"},{"id":"MEJE-KW-001772","row_version":2,"title":"화면을 가로막는 팝업 광고","original":"Annoying Pop-Up Ad","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"작품 속 화면에 광고창이 갑자기 떠서 인물이나 플레이어의 행동을 방해하는 장치. 광고의 실제 수익 구조보다 닫기 어려운 인터페이스와 방해 효과가 핵심이다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001772/index.html"},{"id":"MEJE-KW-001773","row_version":3,"title":"도움보다 방해가 되는 게임 안내자","original":"Annoying Video Game Helper","aliases":[],"kind":"keyword","facet_id":"ML-F25","node_kind":null,"parent_id":null,"tag_path":["ML-F25"],"summary":"플레이어를 돕도록 배치된 동료나 안내자가 같은 설명을 반복하거나 필요한 순간의 조작을 끊는 구성. 정보 제공 기능과 플레이 경험의 불편이 충돌한다. 플레이 불편을 줄이는 편의 기능과 연결해 안내가 플레이를 돕는 시점과 방해하는 시점을 비교할 수 있다.","accent":"#667E94","tab":"#9A6A55","facet":"게임·상호작용","bookmark":"분류축","entry_url":"cards/MEJE-KW-001773/index.html"},{"id":"MEJE-KW-001774","row_version":2,"title":"주인공을 따라다니며 방해하는 어린 형제자매","original":"Annoying Younger Sibling","aliases":[],"kind":"keyword","facet_id":"ML-F10","node_kind":null,"parent_id":null,"tag_path":["ML-F10"],"summary":"어린 형제자매가 주인공의 물건이나 시간을 침범하면서 갈등을 일으키는 관계 유형. 나이나 성별의 속성보다 친밀한 가족 사이의 경계 침범에 초점을 둔다.","accent":"#9D7C82","tab":"#9A6A55","facet":"관계","bookmark":"분류축","entry_url":"cards/MEJE-KW-001774/index.html"},{"id":"MEJE-KW-001775","row_version":1,"title":"출시 연도를 제목에 붙인 작품","original":"Annual Title","aliases":[],"kind":"keyword","facet_id":"ML-F23","node_kind":null,"parent_id":null,"tag_path":["ML-F23"],"summary":"작품명에 발표 연도나 다음 연도를 넣어 당대성과 판본을 알리는 명명 방식. 배경 연도를 가리키는 제목과는 구별한다.","accent":"#7C808E","tab":"#9A6A55","facet":"서술·언어·정보","bookmark":"분류축","entry_url":"cards/MEJE-KW-001775/index.html"},{"id":"MEJE-KW-001776","row_version":1,"title":"침대 밖에서 잠드는 인물","original":"An Odd Place to Sleep","aliases":[],"kind":"keyword","facet_id":"ML-F09","node_kind":null,"parent_id":null,"tag_path":["ML-F09"],"summary":"늘 뜻밖의 장소에서 잠을 청하는 습관으로 인물의 생활 조건이나 성격을 드러낸다. 고단한 경험, 낯선 종족의 생태, 익숙한 안식처에 대한 거리감 등 이유는 작품마다 다르다.","accent":"#7B7594","tab":"#9A6A55","facet":"인물","bookmark":"분류축","entry_url":"cards/MEJE-KW-001776/index.html"}]}.cards;